					logger.Error("unmarshalling from cache", zap.Error(err))
					return handler(ctx, req)
				}

				logger.Debug("get flag hit", zap.Stringer("response", resp))
				return resp, nil
			}

			logger.Debug("get flag miss")
			resp, err := handler(ctx, req)
			if err != nil {
				return nil, err
			}

